package org.novasos.healthysv2.patient;
import static org.assertj.core.api.Assertions.*; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test;
class ConsentTests {
 @Test void grantsRevokesAndExpiresConsent(){UUID patient=UUID.randomUUID(),person=UUID.randomUUID();Instant now=Instant.parse("2026-09-21T12:00:00Z");Consent active=Consent.grant(patient,person,null,"medical_record","Care",null,now,now.plusSeconds(60));assertThat(active.grants("MEDICAL_RECORD",person,null,now)).isTrue();active.revoke(now.plusSeconds(1),"Patient request");assertThat(active.getStatus()).isEqualTo("REVOKED");assertThat(active.grants("MEDICAL_RECORD",person,null,now.plusSeconds(2))).isFalse();Consent expiring=Consent.grant(patient,person,null,"FULL_RECORD",null,null,now,now.plusSeconds(1));assertThat(expiring.refreshStatus(now.plusSeconds(2))).isTrue();assertThat(expiring.getStatus()).isEqualTo("EXPIRED");}
 @Test void enforcesXorGranteeAndDates(){assertThatThrownBy(()->Consent.grant(UUID.randomUUID(),null,null,"RECORD",null,null,null,null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->Consent.grant(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"RECORD",null,null,null,null)).isInstanceOf(IllegalArgumentException.class);Instant now=Instant.now();assertThatThrownBy(()->Consent.grant(UUID.randomUUID(),UUID.randomUUID(),null,"RECORD",null,null,now,now.minusSeconds(1))).isInstanceOf(IllegalArgumentException.class);}
}
